// Clasifica los workflows archivados según retención y etiqueta de protección.
const config = $('config').first().json;
const retention_days = Number(config.retention_days);
const project_id = String(config.project_id ?? '').trim();
const protected_tag = String(config.protected_tag ?? 'keep').trim().toLowerCase();

// Valida la configuración antes de evaluar los workflows archivados.
if (!Number.isFinite(retention_days) || retention_days < 1) {
  throw new Error('retention_days must be a number greater than 0');
}
if (!config.dry_run && !project_id) {
  throw new Error('Set project_id before changing dry_run to false');
}

const archived_workflows = $input.all();
const now_ms = Date.now();
const cutoff_ms = now_ms - retention_days * 86_400_000;
const stats = {
  total_archived: archived_workflows.length,
  to_delete: 0,
  not_deleted_by_retention: 0,
  not_deleted_by_protected_tag: 0,
};
const candidates = [];

// Asigna cada workflow archivado a una única categoría estadística.
for (const input_item of archived_workflows) {
  const workflow_data = input_item.json;
  const workflow_id = String(workflow_data.id ?? '').trim();
  const updated_at_ms = Date.parse(workflow_data.updatedAt);

  if (!workflow_id || !Number.isFinite(updated_at_ms)) {
    throw new Error('Every archived workflow must include id and updatedAt');
  }

  if (updated_at_ms >= cutoff_ms) {
    stats.not_deleted_by_retention += 1;
    continue;
  }

  // Normaliza las etiquetas para aplicar la protección sin distinguir mayúsculas.
  const tags = (Array.isArray(workflow_data.tags) ? workflow_data.tags : [])
    .map((tag) => String(typeof tag === 'string' ? tag : tag?.name ?? '').trim().toLowerCase())
    .filter(Boolean);

  if (protected_tag && tags.includes(protected_tag)) {
    stats.not_deleted_by_protected_tag += 1;
    continue;
  }

  stats.to_delete += 1;
  candidates.push({
    id: workflow_id,
    name: String(workflow_data.name ?? ''),
    updated_at: workflow_data.updatedAt,
    age_days: Math.floor((now_ms - updated_at_ms) / 86_400_000),
    tags,
  });
}

// Devuelve candidatos y estadísticas que forman una partición del total archivado.
return [{
  json: {
    cutoff_at: new Date(cutoff_ms).toISOString(),
    stats,
    candidates,
  },
}];

// Resume la simulación o eliminación con estadísticas exclusivas de workflows archivados.
const config = $('config').first().json;
const selection = $('select_candidates').first().json;

// Normaliza los resultados recibidos desde la rama ejecutada.
const results = $input.all().map((input_item) => input_item.json);
const deletion_enabled = !config.dry_run && selection.stats.to_delete > 0;

// Separa resultados correctos y fallidos cuando la eliminación está habilitada.
const failures = deletion_enabled ? results.filter((result) => result?.error) : [];
const successes = deletion_enabled ? results.filter((result) => !result?.error) : [];
const not_processed = deletion_enabled
  ? Math.max(selection.stats.to_delete - results.length, 0)
  : 0;

// Calcula el estado final usando directamente el valor de dry_run.
const status = selection.stats.to_delete === 0
  ? 'NOTHING_TO_DO'
  : config.dry_run
    ? 'PREVIEW'
    : failures.length || not_processed
      ? 'PARTIAL'
      : 'SUCCESS';

// Extrae mensajes legibles de los errores devueltos por n8n.
const error_messages = failures.map((result) => result.error?.message ?? String(result.error));

return [{
  json: {
    status,
    dry_run: config.dry_run,
    generated_at: new Date().toISOString(),
    retention_days: config.retention_days,
    project_id: config.project_id,
    protected_tag: config.protected_tag,
    cutoff_at: selection.cutoff_at,
    stats: selection.stats,
    attempted_count: deletion_enabled ? results.length : 0,
    deleted_count: successes.length,
    failed_count: failures.length,
    not_processed_count: not_processed,
    candidates: selection.candidates,
    errors: error_messages,
  },
}];
